//! Tiled (mapeditor.org) TMJ import: parse a Tiled JSON export and convert
//! the authored object layers into runtime geography data.
//!
//! Pixel coordinates are converted to world km via the projection
//! (`px / tmj_dims * km_dims`), then to sim tiles via `KM_PER_CELL`.
//! The authored Tiled layers are the single source of truth for positions
//! and geometry; `hoatool map import` is a thin CLI over [`import_tiled`]
//! that writes `geography.toml` + `manifest.toml` (the LOD pyramid is
//! generated by `hoatool gen-map`, not by import).

use std::path::Path;

use anyhow::{Context, Result, bail};

use crate::content::load::GEOGRAPHY_VERSION;
use crate::world::geo::{KmPoint, KmPolyline};
use crate::world::{KM_PER_CELL, River, Route, Settlement, World};

/// Manifest for the committed geography (TMJ source dimensions).
#[derive(Debug, serde::Deserialize, serde::Serialize)]
pub struct MapManifest {
    pub version: u32,
    pub tmj_width_px: u32,
    pub tmj_height_px: u32,
}

impl MapManifest {
    pub fn new(tmj_width_px: u32, tmj_height_px: u32) -> Self {
        MapManifest {
            version: 1,
            tmj_width_px,
            tmj_height_px,
        }
    }
}

/// Projection built from the TMJ map dimensions.
#[derive(Debug, Clone, Copy)]
pub struct ImportProjection {
    tmj_width_px: f64,
    tmj_height_px: f64,
    km_width: f64,
    km_height: f64,
}

impl ImportProjection {
    pub fn new(tmj_width_px: u32, tmj_height_px: u32, km_width: f64, km_height: f64) -> Self {
        ImportProjection {
            tmj_width_px: tmj_width_px as f64,
            tmj_height_px: tmj_height_px as f64,
            km_width,
            km_height,
        }
    }

    /// Pixel position -> world-km coordinates.
    pub fn px_to_km(&self, px: f64, py: f64) -> (f64, f64) {
        (
            px / self.tmj_width_px * self.km_width,
            py / self.tmj_height_px * self.km_height,
        )
    }

    /// World-km -> sim tile.
    pub fn km_to_tile(&self, km_x: f64, km_y: f64) -> (u32, u32) {
        let x = (km_x / KM_PER_CELL).floor().max(0.0) as u32;
        let y = (km_y / KM_PER_CELL).floor().max(0.0) as u32;
        (x, y)
    }
}

/// Parse a Tiled JSON export and extract geography data.
///
/// Settlements and landmarks are point objects; rivers and routes are
/// polylines; regions are polygons. Custom properties carry metadata
/// (polity, navigable, width_class, seasonal, from, to, risky, modes,
/// blocked, kind). Missing properties fall back to safe defaults.
pub fn import_tiled(tsx_path: &Path, world: &World) -> Result<(GeographyToml, MapManifest)> {
    let text = std::fs::read_to_string(tsx_path)
        .with_context(|| format!("reading {}", tsx_path.display()))?;
    let map: TiledMap = serde_json::from_str(&text)
        .with_context(|| format!("parsing TMJ JSON from {}", tsx_path.display()))?;

    let proj = ImportProjection::new(
        map.width * map.tilewidth,
        map.height * map.tileheight,
        world.width as f64 * KM_PER_CELL,
        world.height as f64 * KM_PER_CELL,
    );

    let mut settlements = Vec::new();
    let mut rivers = Vec::new();
    let mut routes = Vec::new();
    let mut regions = Vec::new();
    let mut landmarks = Vec::new();

    for layer in &map.layers {
        if layer.layer_type != "objectgroup" {
            continue;
        }
        for obj in &layer.objects {
            match layer.name.as_str() {
                "settlements" => {
                    let (km_x, km_y) = proj.px_to_km(obj.x, obj.y);
                    let (tx, ty) = proj.km_to_tile(km_x, km_y);
                    if tx >= world.width || ty >= world.height {
                        bail!(
                            "settlement {:?} at pixel ({}, {}) maps to tile ({}, {}) \
                             which is outside the {}×{} map",
                            obj.name,
                            obj.x,
                            obj.y,
                            tx,
                            ty,
                            world.width,
                            world.height
                        );
                    }
                    let polity = obj
                        .properties
                        .iter()
                        .find(|p| p.name == "polity")
                        .and_then(|p| p.value.as_str())
                        .unwrap_or("Unknown");
                    settlements.push(Settlement {
                        id: obj.name.clone(),
                        name: obj.name.clone(),
                        polity: polity.to_string(),
                        x: tx,
                        y: ty,
                        places: Vec::new(),
                    });
                }
                "rivers" => {
                    let points_km: Vec<(f64, f64)> = if let Some(polyline) = &obj.polyline {
                        polyline
                            .iter()
                            .map(|p| proj.px_to_km(obj.x + p.x, obj.y + p.y))
                            .collect()
                    } else if let Some(polygon) = &obj.polygon {
                        polygon
                            .iter()
                            .map(|p| proj.px_to_km(obj.x + p.x, obj.y + p.y))
                            .collect()
                    } else {
                        vec![proj.px_to_km(obj.x, obj.y)]
                    };
                    let points_tile: Vec<(u32, u32)> = points_km
                        .iter()
                        .map(|&(kx, ky)| proj.km_to_tile(kx, ky))
                        .collect();
                    let km_polyline = KmPolyline {
                        id: obj.name.clone(),
                        points: points_km.iter().map(|&(x, y)| KmPoint::new(x, y)).collect(),
                    };
                    let length_km = km_polyline.length_km();
                    let navigable = obj
                        .properties
                        .iter()
                        .find(|p| p.name == "navigable")
                        .and_then(|p| p.value.as_bool())
                        .unwrap_or(true);
                    let width_class = obj
                        .properties
                        .iter()
                        .find(|p| p.name == "width_class")
                        .and_then(|p| p.value.as_str())
                        .unwrap_or("normal")
                        .to_string();
                    let seasonal = obj
                        .properties
                        .iter()
                        .find(|p| p.name == "seasonal")
                        .and_then(|p| p.value.as_str())
                        .map(|s| s.to_string());
                    rivers.push(River {
                        id: obj.name.clone(),
                        name: obj.name.clone(),
                        points: points_tile,
                        length_km,
                        width_class,
                        navigable,
                        seasonal,
                    });
                }
                "routes" => {
                    let polyline = obj
                        .polyline
                        .as_ref()
                        .ok_or_else(|| anyhow::anyhow!("route {:?} has no polyline", obj.name))?;
                    let points_km: Vec<(f64, f64)> = polyline
                        .iter()
                        .map(|p| proj.px_to_km(obj.x + p.x, obj.y + p.y))
                        .collect();
                    let points_tile: Vec<(u32, u32)> = points_km
                        .iter()
                        .map(|&(kx, ky)| proj.km_to_tile(kx, ky))
                        .collect();
                    let km_polyline = KmPolyline {
                        id: obj.name.clone(),
                        points: points_km.iter().map(|&(x, y)| KmPoint::new(x, y)).collect(),
                    };
                    let path_km = km_polyline.length_km();
                    let from = obj
                        .properties
                        .iter()
                        .find(|p| p.name == "from")
                        .and_then(|p| p.value.as_str())
                        .ok_or_else(|| {
                            anyhow::anyhow!("route {:?} missing 'from' property", obj.name)
                        })?
                        .to_string();
                    let to = obj
                        .properties
                        .iter()
                        .find(|p| p.name == "to")
                        .and_then(|p| p.value.as_str())
                        .ok_or_else(|| {
                            anyhow::anyhow!("route {:?} missing 'to' property", obj.name)
                        })?
                        .to_string();
                    let risky = obj
                        .properties
                        .iter()
                        .find(|p| p.name == "risky")
                        .and_then(|p| p.value.as_bool())
                        .unwrap_or(false);
                    let modes: Vec<String> = obj
                        .properties
                        .iter()
                        .find(|p| p.name == "modes")
                        .and_then(|p| p.value.as_array())
                        .map(|arr| {
                            arr.iter()
                                .filter_map(|v| v.as_str().map(|s| s.to_string()))
                                .collect()
                        })
                        .unwrap_or_else(|| vec!["caravan".to_string()]);
                    let seasonal = obj
                        .properties
                        .iter()
                        .find(|p| p.name == "seasonal")
                        .and_then(|p| p.value.as_bool())
                        .unwrap_or(false);
                    let blocked = obj
                        .properties
                        .iter()
                        .find(|p| p.name == "blocked")
                        .and_then(|p| p.value.as_bool())
                        .unwrap_or(false);
                    routes.push(Route {
                        id: obj.name.clone(),
                        from,
                        to,
                        risky,
                        path_km,
                        tiles: points_tile,
                        modes,
                        seasonal,
                        blocked,
                    });
                }
                "regions" => {
                    let polygon = obj
                        .polygon
                        .as_ref()
                        .ok_or_else(|| anyhow::anyhow!("region {:?} has no polygon", obj.name))?;
                    let ring_km: Vec<(f64, f64)> = polygon
                        .iter()
                        .map(|p| proj.px_to_km(obj.x + p.x, obj.y + p.y))
                        .collect();
                    regions.push(GeographyRegion {
                        id: obj.name.clone(),
                        polygon: ring_km,
                    });
                }
                "landmarks" => {
                    let (km_x, km_y) = proj.px_to_km(obj.x, obj.y);
                    let kind = obj
                        .properties
                        .iter()
                        .find(|p| p.name == "kind")
                        .and_then(|p| p.value.as_str())
                        .unwrap_or("landmark")
                        .to_string();
                    landmarks.push(GeographyLandmark {
                        id: obj.name.clone(),
                        kind,
                        point: (km_x, km_y),
                    });
                }
                _ => {}
            }
        }
    }

    let manifest = MapManifest::new(map.width * map.tilewidth, map.height * map.tileheight);

    Ok((
        GeographyToml {
            version: GEOGRAPHY_VERSION,
            settlements,
            rivers,
            routes,
            regions,
            landmarks,
        },
        manifest,
    ))
}

// ---------------------------------------------------------------------------
// Tiled JSON deserialization (subset of the TMJ format)
// ---------------------------------------------------------------------------

#[derive(serde::Deserialize)]
struct TiledMap {
    width: u32,
    height: u32,
    tilewidth: u32,
    tileheight: u32,
    #[serde(default)]
    layers: Vec<TiledLayer>,
}

#[derive(serde::Deserialize)]
struct TiledLayer {
    #[serde(rename = "type")]
    layer_type: String,
    name: String,
    #[serde(default)]
    objects: Vec<TiledObject>,
}

#[derive(serde::Deserialize)]
struct TiledObject {
    #[allow(dead_code)]
    id: u64,
    name: String,
    #[serde(default)]
    x: f64,
    #[serde(default)]
    y: f64,
    #[allow(dead_code)]
    #[serde(default)]
    width: f64,
    #[allow(dead_code)]
    #[serde(default)]
    height: f64,
    #[serde(default)]
    polyline: Option<Vec<TiledPoint>>,
    #[serde(default)]
    polygon: Option<Vec<TiledPoint>>,
    #[serde(default)]
    #[allow(dead_code)]
    point: bool,
    #[serde(default)]
    properties: Vec<TiledProperty>,
}

#[derive(serde::Deserialize)]
struct TiledPoint {
    x: f64,
    y: f64,
}

#[derive(serde::Deserialize)]
struct TiledProperty {
    name: String,
    #[serde(default)]
    value: serde_json::Value,
}

// ---------------------------------------------------------------------------
// Geography TOML output types
// ---------------------------------------------------------------------------

/// Serialized `geography.toml` (written by `hoatool map import`, read back
/// by `content::load::load_world`).
#[derive(Debug, serde::Serialize)]
pub struct GeographyToml {
    pub version: u32,
    pub settlements: Vec<Settlement>,
    pub rivers: Vec<River>,
    pub routes: Vec<Route>,
    pub regions: Vec<GeographyRegion>,
    pub landmarks: Vec<GeographyLandmark>,
}

/// Region polygon in world-km coordinates.
#[derive(Debug, serde::Serialize)]
pub struct GeographyRegion {
    pub id: String,
    pub polygon: Vec<(f64, f64)>,
}

/// Landmark point in world-km coordinates.
#[derive(Debug, serde::Serialize)]
pub struct GeographyLandmark {
    pub id: String,
    pub kind: String,
    pub point: (f64, f64),
}
